import { ChangeDetectionStrategy, Component, ElementRef, effect, inject, ViewChild } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import type { AlertAcknowledgementReason, AlertInstance, AlertSuppression, Dashboard, DashboardPanel, DashboardPreset, Incident, IncidentImpact, IncidentState, OperationalSeverity, SavedQuery } from '@aura/observatory-api-client';
import { dashboardExecutionKey, OperationsWorkspaceStore, type OperationsWorkspaceTab, type DashboardExecution } from './operations-workspace.store';
import { ObservatoryStore } from '../../observatory-store';
import { ObservatoryIconComponent } from '../../presentation/observatory-icon.component';

const severityOptions: ReadonlyArray<OperationalSeverity> = ['info', 'warning', 'error', 'critical'];
const impactOptions: ReadonlyArray<IncidentImpact> = ['none', 'limited', 'degraded', 'major', 'critical'];
const incidentStates: ReadonlyArray<IncidentState> = ['open', 'investigating', 'mitigated', 'resolved', 'closed'];
const acknowledgementReasons: ReadonlyArray<AlertAcknowledgementReason> = ['investigating', 'known_issue', 'accepted_risk', 'false_positive'];
const targetTypes = ['run', 'deployment', 'experiment', 'regression', 'incident'] as const;

@Component({
  selector: 'observatory-operations-workspace',
  standalone: true,
  imports: [CommonModule, DatePipe, FormsModule, ObservatoryIconComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="operations" aria-labelledby="operations-title">
      <div class="section-heading">
        <div><p class="eyebrow">Owner operations</p><h2 id="operations-title" tabindex="-1">Dashboards, alerts, and incidents</h2><p class="muted">Bounded operational workflows. Alerts stay inside Observatory and annotation text is never sent through telemetry or live events.</p></div>
        <div class="heading-actions"><span class="state-chip" [class]="'state-' + store.state()" role="status">{{ stateLabel() }}</span><button type="button" class="secondary-button" (click)="refresh()" [disabled]="!!store.busyAction()">Refresh</button></div>
      </div>
      @if (store.notice(); as notice) { <p class="notice" role="status" aria-live="polite">{{ notice }}</p> }
      @if (store.error(); as error) { <div class="state-panel failure" role="alert"><strong>{{ store.state() === 'unauthorized' ? 'Owner sign-in required' : store.state() === 'rejected' ? 'Some operation data was rejected' : store.state() === 'unavailable' ? 'Operation service unavailable' : 'Operations need attention' }}</strong><p>{{ error }}</p>@if (store.state() !== 'unauthorized') { <button type="button" (click)="refresh()" [disabled]="!!store.busyAction()">Retry operation views</button> }@else { <p class="muted">Use the owner sign-in recovery above, then return to this workspace.</p> }</div> }
      @if (store.state() === 'loading') { <div class="state-panel" role="status" aria-busy="true"><strong>Loading operation views</strong><p>{{ hasSnapshot() ? 'Refreshing the bounded snapshot; the previous data remains visible.' : 'Fetching the latest bounded owner snapshot…' }}</p></div> }
      @if (store.state() === 'disconnected') { <div class="state-panel warning" role="status"><strong>Live operation updates are disconnected</strong><p>The last snapshot remains visible. Reconnect or refresh to catch up.</p><button type="button" (click)="refresh()">Reconnect</button></div> }
      @if (store.lastUpdatedAt(); as updatedAt) { <p class="snapshot-age" role="status"><span>Observed <time [dateTime]="updatedAt">{{ snapshotAge(updatedAt) }}</time></span>@if (store.lastFetchedAt(); as fetchedAt) { <span class="freshness-detail">Last fetched {{ snapshotAge(fetchedAt) }}</span> }@if (isSnapshotStale(updatedAt)) { <span class="state-chip state-stale">stale snapshot</span> }</p> }
      <div class="workspace-metrics" aria-label="Operations workspace summary"><div><span>Dashboards</span><strong>{{ dashboards().length }}</strong></div><div><span>Firing alerts</span><strong>{{ store.alertCount() }}</strong></div><div><span>Open incidents</span><strong>{{ store.openIncidentCount() }}</strong></div><p>Review current signals first; authoring controls stay below the evidence lists.</p></div>
      <style>.workspace-metrics{align-items:center;background:var(--surface-raised);border:1px solid var(--border);display:flex;flex-wrap:wrap;gap:.8rem 1.4rem;padding:.8rem 1rem}.workspace-metrics div{display:grid;gap:.1rem;min-width:7rem}.workspace-metrics span{color:var(--text-muted);font-size:.72rem;font-weight:750;text-transform:uppercase}.workspace-metrics strong{font-size:1.2rem}.workspace-metrics p{color:var(--text-muted);font-size:.82rem;margin:0 0 0 auto}@media(max-width:640px){.workspace-metrics p{flex-basis:100%;margin:0}}</style>
      <style>.operations{gap:var(--obs-section-gap)}.section-heading>div{max-width:var(--obs-prose-max)}.workspace-grid{align-items:start;gap:1.5rem;grid-template-columns:minmax(0,2fr) minmax(0,3fr)}.workspace-grid>.panel{align-self:start}.workspace-grid > .panel:first-child{order:2}.workspace-grid > .panel:nth-child(2){order:1}.panel{border-radius:.65rem;padding:clamp(1.25rem,2vw,1.75rem)}.workspace-tabs{gap:.35rem;padding-bottom:1px}.workspace-tabs button{padding-inline:1rem}.table-wrap:has(td[colspan]){overflow:visible}.table-wrap:has(td[colspan]) table{min-width:0}.notice,.warning,.failure{border-left:3px solid currentColor;border-radius:.45rem}@media(max-width:640px){.panel{padding:1rem}.workspace-tabs button{padding-inline:.75rem}.workspace-grid{gap:1rem;grid-template-columns:1fr}}</style>
      <style>.confirmation-dialog{margin:auto}@media(forced-colors:active){.primary-button{background:ButtonFace !important;border:2px solid ButtonBorder !important;color:ButtonText !important;forced-color-adjust:auto}}</style>
      <style>.workspace-tab-select{display:none;gap:.3rem;color:var(--text-muted);font-size:.78rem;font-weight:750}.workspace-tab-select select{margin-top:.1rem}.snapshot-age{align-items:center;display:flex;flex-wrap:wrap;gap:.45rem .8rem}.snapshot-age .state-chip{margin-left:0}.table-wrap[tabindex="0"]{outline-offset:3px}.table-wrap[tabindex="0"]:focus-visible{outline:3px solid var(--focus)}.table-wrap[tabindex="0"]::after{color:var(--text-muted);content:'Scroll horizontally for more columns when needed.';display:block;font-size:.72rem;padding:.35rem .45rem}@media(max-width:700px){.workspace-tabs{display:none}.workspace-tab-select{display:grid}}</style>

      @if (store.state() === 'loading' && !hasSnapshot()) { <div class="workspace-skeleton" role="status" aria-busy="true"><span></span><span></span><span></span><p>Loading owner operation workspaces…</p></div> } @else {

      <nav class="workspace-tabs" aria-label="Operations workspaces">
        @for (tab of tabs; track tab.id) { <button type="button" [class.active]="store.activeTab() === tab.id" [attr.aria-current]="store.activeTab() === tab.id ? 'page' : null" (click)="openTab(tab.id)">{{ tab.label }}@if (tab.id === 'alerts' && store.alertCount()) { <span class="tab-count" aria-label="firing alerts">{{ store.alertCount() }}</span> }@if (tab.id === 'incidents' && store.openIncidentCount()) { <span class="tab-count" aria-label="open incidents">{{ store.openIncidentCount() }}</span> }</button> }
      </nav>
      <label class="workspace-tab-select">Workspace <select aria-label="Operations workspace" [value]="store.activeTab()" (change)="selectTabFromEvent($event)">@for (tab of tabs; track tab.id) { <option [value]="tab.id">{{ tab.label }}</option> }</select></label>

      @if (store.activeTab() === 'dashboards') {
        <section class="workspace-grid" aria-labelledby="dashboard-heading"><div class="panel"><div class="panel-heading"><div><h3 id="dashboard-heading">Dashboard composition</h3><p class="muted">Use a saved query as a versioned panel. Presets are immutable service-owned definitions.</p></div></div>
          <form class="form-grid" (ngSubmit)="createDashboard()"><label>Dashboard name<input name="dashboard-name" [(ngModel)]="dashboardName" required maxlength="120" autocomplete="off" /></label><label>Description<input name="dashboard-description" [(ngModel)]="dashboardDescription" maxlength="400" autocomplete="off" /></label><label>Panel query<select name="dashboard-query" [(ngModel)]="dashboardQueryKey" required><option value="">Select a saved query</option>@for (query of queries(); track query.queryId + query.queryVersion) { <option [value]="query.queryId + '|' + query.queryVersion">{{ query.name }} · v{{ query.queryVersion }}</option> }</select></label><button class="primary-button" type="submit" [disabled]="!!store.busyAction() || store.state() === 'loading'">Create dashboard</button></form>@if (dashboardError) { <p class="inline-error" role="alert">{{ dashboardError }}</p> }
          @if (!queries().length) { <p class="empty" role="status">No saved queries yet. Create one in the Saved queries workspace before composing a dashboard.</p> }
        </div><div class="panel"><h3>Immutable presets</h3><div class="card-list">@for (preset of presets(); track preset.presetId + preset.presetVersion) { <article class="mini-card"><div><h4>{{ preset.name }}</h4><p class="muted">{{ preset.kind }} · {{ preset.panels.length }} panels · v{{ preset.presetVersion }}</p></div><span class="state-chip state-ready">Immutable</span></article>} @empty { <p class="empty">No presets were returned.</p> }</div></div></section>
        <section class="panel" aria-labelledby="dashboard-list-heading"><div class="panel-heading"><h3 id="dashboard-list-heading">Saved dashboards</h3><span class="muted">{{ dashboards().length }} loaded</span></div><div class="table-wrap" role="region" tabindex="0" aria-label="Saved dashboards table. Use horizontal scrolling for additional columns."><table><caption class="sr-only">Saved Observatory dashboards</caption><thead><tr><th scope="col">Name</th><th scope="col">Panels</th><th scope="col">Version</th><th scope="col">Created</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>@if (store.state() !== 'loading' || dashboards().length) {@for (dashboard of dashboards(); track dashboard.dashboardId + dashboard.dashboardVersion) { <tr><th scope="row">{{ dashboard.name }}</th><td>{{ dashboard.panels.length }}</td><td>{{ dashboard.dashboardVersion }}</td><td>{{ dashboard.createdAt | date:'short':'UTC' }} UTC</td><td><button type="button" (click)="selectDashboard(dashboard)" [attr.aria-pressed]="selectedDashboard?.dashboardId === dashboard.dashboardId">View panels</button></td></tr>} @empty { <tr><td colspan="5">No owner dashboards match the current snapshot.</td></tr> }}</tbody></table></div></section>
        @if (selectedDashboard; as dashboard) { <section class="panel dashboard-preview" aria-labelledby="dashboard-preview-heading"><div class="panel-heading"><div><h3 id="dashboard-preview-heading">{{ dashboard.name }} panel workspace</h3><p class="muted">Each panel executes its exact saved query. Freshness is taken from the analytics response, not browser fetch time.</p></div><span class="state-chip state-ready">{{ dashboard.panels.length }} panels</span></div><div class="dashboard-panels">@for (panel of dashboard.panels; track panel.panelId) { <article class="dashboard-panel"><div class="panel-heading"><h4>{{ panel.title }}</h4><span class="muted">{{ panelVisualizationLabel(panel) }} · {{ panel.size }}</span></div>@if (dashboardExecution(panel); as execution) {@if (execution.state === 'loading' && !execution.snapshot && !execution.result) { <div class="dashboard-skeleton" role="status" aria-busy="true">Loading measured data…</div> } @else if (execution.state === 'incompatible') { <div class="state-panel warning" role="alert"><strong>Incompatible panel</strong><p>{{ execution.error }}</p><p class="terminal-note">This combination is terminal until the saved-query version or panel visualization is changed.</p></div> } @else if (execution.result; as result) { @if (result.kind !== 'analytics') { <p class="metric-freshness" role="status">{{ dashboardResultFreshness(execution, result) }} · measured metadata</p>@if (execution.state === 'loading') { <p class="state-panel warning" role="status">Refreshing this panel; the prior measured result remains visible.</p> } @if (execution.state === 'error') { <div class="state-panel failure" role="alert"><strong>Panel refresh failed</strong><p>{{ execution.error }}</p><button type="button" (click)="retryDashboard(panel)">Retry panel</button></div> }@if (result.kind === 'run_search' || result.kind === 'trace_search') { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} results. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} {{ result.kind === 'trace_search' ? 'trace candidates' : 'runs' }}</caption><thead><tr><th scope="col">Run</th><th scope="col">Status</th><th scope="col">Component(s)</th><th scope="col">Model</th><th scope="col">Deployment</th><th scope="col">Duration</th><th scope="col">Trace</th></tr></thead><tbody>@for (run of result.value.items; track run.runId) { <tr><th scope="row" class="mono">{{ run.runId }}</th><td>{{ run.status }}</td><td>{{ run.componentIds.join(', ') }}</td><td>{{ run.model ?? '—' }}</td><td>{{ run.deploymentId }}</td><td>{{ run.durationMs ?? '—' }} ms</td><td class="mono">{{ run.traceId ?? '—' }}</td></tr> } @empty { <tr><td colspan="7">No {{ result.kind === 'trace_search' ? 'trace candidates' : 'runs' }} matched this bounded query.</td></tr> }</tbody></table></div> } @else if (result.kind === 'run_comparison') { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} comparison. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} run comparison</caption><thead><tr><th scope="col">Side</th><th scope="col">Run</th><th scope="col">Status</th><th scope="col">Outcome</th><th scope="col">Duration</th><th scope="col">Evidence</th><th scope="col">Partial</th></tr></thead><tbody>@for (side of [result.value.left, result.value.right]; track side.role) { <tr><th scope="row">{{ side.role }}</th><td class="mono">{{ side.runId }}</td><td>{{ side.status }}</td><td>{{ side.outcome }}</td><td>{{ side.durationMs ?? '—' }} ms</td><td>{{ side.evidence }}</td><td>{{ side.partial ? 'Partial' : 'Complete' }}</td></tr> }</tbody></table></div> } @else if (result.kind === 'regression_search') { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} regression. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} regression decisions</caption><thead><tr><th scope="col">Regression</th><th scope="col">Decision</th><th scope="col">Evidence</th><th scope="col">Created</th></tr></thead><tbody>@for (regression of result.value.items; track regression.regressionId) { <tr><th scope="row" class="mono">{{ regression.regressionId }}</th><td>{{ regression.decision }}</td><td>{{ regression.evidenceState }}</td><td>{{ regression.createdAt }}</td></tr> } @empty { <tr><td colspan="4">No regression decisions matched this bounded query.</td></tr> }</tbody></table></div> } @else { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} health. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} component health</caption><thead><tr><th scope="col">UTC interval</th><th scope="col">Samples</th><th scope="col">P50 ms</th><th scope="col">P95 ms</th><th scope="col">Error rate</th><th scope="col">State</th></tr></thead><tbody>@for (point of healthPoints(result); track point.startAt + point.endAt) { <tr><th scope="row">{{ point.startAt }} – {{ point.endAt }}</th><td>{{ point.summary.sampleCount }}</td><td>{{ point.summary.latencyP50Ms ?? '—' }}</td><td>{{ point.summary.latencyP95Ms ?? '—' }}</td><td>{{ point.summary.errorRate ?? '—' }}</td><td>Summary point</td></tr> } @empty { <tr><td colspan="6">No component health points matched this bounded query.</td></tr> }</tbody></table></div> } } } @else if (execution.snapshot; as snapshot) { <p class="metric-freshness" role="status">{{ dashboardExecutionFreshness(execution, snapshot) }} · {{ dashboardState(snapshot) }}</p>@if (execution.state === 'loading') { <p class="state-panel warning" role="status">Refreshing this panel; the prior measured snapshot remains visible.</p> } @if (execution.state === 'error') { <div class="state-panel warning" role="alert"><p>Refresh failed; the prior measured snapshot remains visible.</p><button type="button" (click)="retryDashboard(panel)">Retry panel</button></div> } @if (snapshot.series.length) { @for (series of snapshot.series; track series.seriesKey) { @if (isTrendVisualization(panel)) { <div class="dashboard-series"><div class="visual-slot">@if (panel.visualization === 'bar') { <div class="chart" role="img" [attr.aria-label]="trendAccessibleName(panel, series.seriesKey)"><span class="bar" *ngFor="let point of series.points" [style.height.%]="barHeight(point.value, series)" [attr.aria-hidden]="true"></span></div> } @else { <svg class="trend-chart" role="img" [attr.aria-label]="trendAccessibleName(panel, series.seriesKey)" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline *ngIf="panel.visualization === 'line'" [attr.points]="linePoints(series)" fill="none" vector-effect="non-scaling-stroke"></polyline><polygon *ngIf="panel.visualization === 'area'" [attr.points]="areaPoints(series)" vector-effect="non-scaling-stroke"></polygon></svg> }</div><div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} measurements. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} UTC point measurements · {{ series.seriesKey }} ({{ snapshot.query.unit }})</caption><thead><tr><th scope="col">UTC interval</th><th scope="col">Value</th><th scope="col">Unit</th><th scope="col">Availability</th><th scope="col">Partial</th></tr></thead><tbody>@for (point of series.points; track point.startAt + point.endAt) { <tr><th scope="row">{{ point.startAt }} – {{ point.endAt }}</th><td>{{ point.value ?? '—' }}</td><td>{{ snapshot.query.unit }}</td><td>{{ point.availability }}</td><td>{{ point.partial ? 'Partial' : 'Complete' }}</td></tr> }</tbody></table></div></div> } @else if (panel.visualization === 'stat') { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} summary. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} summary statistic · {{ series.seriesKey }}</caption><thead><tr><th scope="col">Series</th><th scope="col">Samples</th><th scope="col">Minimum</th><th scope="col">P95</th><th scope="col">Maximum</th><th scope="col">Unit</th></tr></thead><tbody><tr><th scope="row">{{ series.seriesKey }}</th><td>{{ series.summary.sampleCount }}</td><td>{{ series.summary.minimum ?? '—' }}</td><td>{{ series.summary.p95 ?? '—' }}</td><td>{{ series.summary.maximum ?? '—' }}</td><td>{{ snapshot.query.unit }}</td></tr></tbody></table></div> } @else { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard result table for {{ panel.title }} measured summary. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panel.title }} measured data · {{ panelVisualizationLabel(panel) }} · {{ series.seriesKey }}</caption><thead><tr><th scope="col">Series</th><th scope="col">Samples</th><th scope="col">P50</th><th scope="col">P95</th><th scope="col">Unit</th></tr></thead><tbody><tr><th scope="row">{{ series.seriesKey }}</th><td>{{ series.summary.sampleCount }}</td><td>{{ series.summary.p50 ?? '—' }}</td><td>{{ series.summary.p95 ?? '—' }}</td><td>{{ snapshot.query.unit }}</td></tr></tbody></table></div> } } } @else { <p class="empty">No measured series matched this query. The service reported no data; no zero was fabricated.</p> } @if (snapshot.breakdowns.length) { <div class="table-scroll" role="region" tabindex="0" aria-label="Dashboard breakdown table for {{ panel.title }}. Use arrow keys to scroll horizontally when needed."><table class="panel-data"><caption>{{ panelVisualizationLabel(panel) }} breakdowns</caption><thead><tr><th scope="col">Group</th><th scope="col">Value</th><th scope="col">Count</th><th scope="col">State</th></tr></thead><tbody>@for (breakdown of snapshot.breakdowns; track breakdown.groupBy + breakdown.value) { <tr><th scope="row">{{ breakdown.groupBy }}</th><td>{{ breakdown.value }}</td><td>{{ breakdown.count }}</td><td>{{ breakdown.partial ? 'Partial' : 'Complete' }}</td></tr> }</tbody></table></div> } } @else { <div class="state-panel failure" role="alert"><strong>{{ execution.state === 'unavailable' ? 'Measurement unavailable' : 'Panel execution failed' }}</strong><p>{{ execution.error ?? 'The saved query did not return a usable analytics snapshot.' }}</p></div> } } </article> } @if (!dashboard.panels.length) { <p class="empty">This dashboard has no panels.</p> }</div></section> }
      }

      @if (store.activeTab() === 'queries') {
        <section class="workspace-grid" aria-labelledby="query-heading"><div class="panel"><h3 id="query-heading">New bounded saved query</h3><p class="muted">This starter query uses a closed analytics schema. Arbitrary SQL, expressions, dimensions, and URLs are not accepted.</p><form class="form-grid" (ngSubmit)="createQuery()"><label>Query name<input name="query-name" [(ngModel)]="queryName" required maxlength="120" autocomplete="off" /></label><label>Metric<select name="query-metric" [(ngModel)]="queryMetric"><option value="operation_duration_ms">Operation duration</option><option value="errors">Errors</option><option value="queue_wait_ms">Queue wait</option></select></label><label>Window<select name="query-window" [(ngModel)]="queryWindow"><option value="fifteen_minutes">15 minutes</option><option value="one_hour">1 hour</option><option value="twenty_four_hours">24 hours</option><option value="seven_days">7 days</option></select></label><button class="primary-button" type="submit" [disabled]="!!store.busyAction() || store.state() === 'loading'">Save bounded query</button></form>@if (queryError) { <p class="inline-error" role="alert">{{ queryError }}</p> }</div><div class="panel"><h3>Saved queries</h3><div class="table-wrap" role="region" tabindex="0" aria-label="Saved queries table. Use horizontal scrolling for additional columns."><table><caption class="sr-only">Bounded saved queries</caption><thead><tr><th scope="col">Name</th><th scope="col">Kind</th><th scope="col">Window</th><th scope="col">Version</th></tr></thead><tbody>@if (store.state() !== 'loading' || queries().length) {@for (query of queries(); track query.queryId + query.queryVersion) { <tr><th scope="row">{{ query.name }}</th><td>{{ query.definition.kind }}</td><td>{{ queryWindowLabel(query) }}</td><td>{{ query.queryVersion }}</td></tr>} @empty { <tr><td colspan="4">No bounded saved queries match the current snapshot.</td></tr> }}</tbody></table></div></div></section>
      }

      @if (store.activeTab() === 'alerts') {
        <section class="panel" aria-labelledby="alert-heading"><div class="panel-heading"><div><h3 id="alert-heading">Alert triage</h3><p class="muted">Repeated symptoms are grouped by a stable content-free identity. Acknowledgement is separate from recovery.</p></div><div class="legend" aria-label="Alert state legend"><span class="legend-item"><observatory-icon name="danger" /> <span>Firing</span></span><span class="legend-item"><observatory-icon name="success" /> <span>Recovered</span></span><span class="legend-item"><observatory-icon name="warning" /> <span>Suppressed</span></span></div></div>
          <div class="table-wrap alert-table-wrap" role="region" tabindex="0" aria-label="Alert instances table. Use horizontal scrolling for additional columns."><table class="alert-table"><caption class="sr-only">Alert instances grouped for triage</caption><thead><tr><th scope="col">Rule / group</th><th scope="col">Severity</th><th scope="col">State</th><th scope="col">Evidence</th><th scope="col">Occurrences</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>@if (store.state() !== 'loading' || instances().length) {@for (instance of instances(); track instance.instanceId) { <tr><th scope="row" data-label="Rule / group"><span class="mono">{{ instance.rule.resourceId }}</span><small>Group {{ instance.groupingId.slice(0, 8) }}</small></th><td data-label="Severity"><span class="severity" [class]="'severity-' + instance.severity">{{ instance.severity }}</span></td><td data-label="State"><span class="state-chip" [class]="'state-' + instance.state">{{ instance.state }}@if (instance.suppressed) { · suppressed }@if (instance.acknowledged) { · acknowledged }</span></td><td data-label="Evidence">{{ instance.evidenceState }}@if (instance.observedValue !== null) { · {{ instance.observedValue }} {{ instance.unit }}}</td><td data-label="Occurrences">{{ instance.occurrenceCount }}</td><td class="row-actions" data-label="Actions"><label class="sr-only" [for]="'ack-reason-' + instance.instanceId">Acknowledgement reason for {{ instance.instanceId }}</label><select [id]="'ack-reason-' + instance.instanceId" [value]="ackReason(instance)" (change)="setAckReason(instance, $any($event.target).value)">@for (reason of acknowledgementReasons; track reason) { <option [value]="reason">{{ reason }}</option> }</select><button type="button" (click)="acknowledge(instance)" [disabled]="instance.acknowledged || !!store.busyAction() || store.state() === 'loading'">Acknowledge</button><button type="button" (click)="suppress(instance)" [disabled]="instance.suppressed || !!store.busyAction() || store.state() === 'loading'">Suppress</button></td></tr>} @empty { <tr><td colspan="6">No alert instances were returned. This is a valid quiet state.</td></tr>} }</tbody></table></div>
        </section><section class="panel" aria-labelledby="suppression-heading"><div class="panel-heading"><h3 id="suppression-heading">Suppression windows</h3><span class="muted">Explicit and time-bounded where configured</span></div><div class="table-wrap" role="region" tabindex="0" aria-label="Alert suppression windows table. Use horizontal scrolling for additional columns."><table><caption class="sr-only">Alert suppression windows</caption><thead><tr><th scope="col">Scope</th><th scope="col">Target</th><th scope="col">Reason</th><th scope="col">State</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>@for (suppression of suppressions(); track suppression.suppressionId) { <tr><th scope="row">{{ suppression.scope }}</th><td class="mono">{{ suppression.target.resourceId }}</td><td>{{ suppression.reason }}</td><td>{{ suppression.state }}</td><td><button type="button" (click)="clearSuppression(suppression)" [disabled]="suppression.state === 'cleared' || !!store.busyAction()">Clear suppression</button></td></tr>} @empty { <tr><td colspan="5">No suppressions are active.</td></tr> }</tbody></table></div></section>
      }

      @if (store.activeTab() === 'incidents') {
        <section class="workspace-grid" aria-labelledby="incident-heading"><div class="panel"><h3 id="incident-heading">Open an incident</h3><p class="muted">Incident state transitions are explicit and audited. Closing requires confirmation.</p><form class="form-grid" (ngSubmit)="createIncident()"><label>Title<input name="incident-title" [(ngModel)]="incidentTitle" required maxlength="160" autocomplete="off" /></label><label>Severity<select name="incident-severity" [(ngModel)]="incidentSeverity">@for (severity of severities; track severity) { <option [value]="severity">{{ severity }}</option> }</select></label><label>Impact<select name="incident-impact" [(ngModel)]="incidentImpact">@for (impact of impacts; track impact) { <option [value]="impact">{{ impact }}</option> }</select></label><fieldset class="wide alert-picker"><legend>Related firing alerts</legend>@for (instance of instances(); track instance.instanceId) {@if (instance.state === 'firing') { <label class="check-label"><input type="checkbox" [checked]="selectedAlertIds.has(instance.instanceId)" (change)="toggleAlert(instance.instanceId)" /> <span>{{ instance.rule.resourceId }} · {{ instance.severity }}</span></label> }} @empty { <p class="muted">No firing alerts are available.</p> }</fieldset><button class="primary-button" type="submit" [disabled]="!!store.busyAction() || store.state() === 'loading' || !selectedAlertIds.size">Create incident</button></form>@if (incidentError) { <p class="inline-error" role="alert">{{ incidentError }}</p> }</div><div class="panel"><h3>Incident lifecycle</h3><div class="card-list">@for (incident of incidents(); track incident.incidentId) { <article class="incident-card"><div class="panel-heading"><div><h4>{{ incident.title }}</h4><p class="muted mono">{{ incident.incidentId }} · v{{ incident.incidentVersion }}</p></div><span class="severity" [class]="'severity-' + incident.severity">{{ incident.severity }}</span></div><p><span class="state-chip" [class]="'state-' + incident.state">{{ incident.state }}</span> <span class="muted">impact: {{ incident.impact }}</span></p>@if (nextStates(incident).length) { <div class="inline-actions"><label class="compact-label">Next state<select [name]="'incident-state-' + incident.incidentId" [ngModel]="nextIncidentState(incident)" (ngModelChange)="setNextIncidentState(incident, $event)">@for (state of nextStates(incident); track state) { <option [value]="state">{{ state }}</option> }</select></label><button type="button" (click)="transitionIncident(incident)" [disabled]="!!store.busyAction()">Transition</button></div> } @else { <p class="terminal-note" role="status">Terminal state: no further transitions are available.</p> }</article>} @empty { <p class="empty">No incidents in the current snapshot.</p> }</div></div></section>
      }

      @if (store.activeTab() === 'annotations') {
        <section class="workspace-grid" aria-labelledby="annotation-heading"><div class="panel"><h3 id="annotation-heading" tabindex="-1">Add an exact-target annotation</h3><p class="muted">Text is owner-authored, bounded to 2,000 characters, and shown only in this REST workspace.</p><form class="form-grid" (ngSubmit)="createAnnotation()"><label>Target type<select name="annotation-type" [(ngModel)]="annotationType">@for (target of targets; track target) { <option [value]="target">{{ target }}</option> }</select></label><label>Target ID<input name="annotation-target" [(ngModel)]="annotationTarget" required maxlength="160" autocomplete="off" /></label><label>Target version<input name="annotation-version" [(ngModel)]="annotationVersion" required maxlength="64" autocomplete="off" /></label><label class="wide">Annotation text<textarea name="annotation-text" [(ngModel)]="annotationText" required maxlength="2000" rows="5"></textarea></label><button class="primary-button" type="submit" [disabled]="!!store.busyAction() || store.state() === 'loading'">Save annotation</button></form>@if (annotationError) { <p class="inline-error" role="alert">{{ annotationError }}</p> }</div><div class="panel"><h3>Recent annotations</h3><div class="card-list">@for (annotation of annotations(); track annotation.annotationId) { <article class="annotation-card"><p class="annotation-text">{{ annotation.text }}</p><p class="muted mono">{{ annotation.target.targetType }} · {{ annotation.target.targetId }} · v{{ annotation.target.targetVersion }}</p><div class="inline-actions"><time class="muted">{{ annotation.createdAt | date:'short':'UTC' }} UTC</time><button type="button" (click)="deleteAnnotation(annotation)" [disabled]="!!store.busyAction() || store.state() === 'loading'">Delete annotation</button></div></article>} @empty { <p class="empty">No annotations in the current snapshot.</p> }</div></div></section>
      }
      }
      @if (pendingConfirmation; as confirmation) { <dialog #confirmationDialog class="confirmation-dialog" aria-labelledby="confirmation-title" aria-describedby="confirmation-description" (cancel)="cancelConfirmation()"><h3 id="confirmation-title">{{ confirmation.title }}</h3><p id="confirmation-description"><strong>Resource:</strong> {{ confirmation.resource }}<br /><strong>Scope:</strong> {{ confirmation.scope }}<br /><strong>Consequence:</strong> {{ confirmation.consequence }}</p>@if (dialogError) { <p class="inline-error" role="alert">{{ dialogError }}</p> }<p role="status" aria-live="polite">{{ dialogBusy ? 'Working…' : '' }}</p><div class="dialog-actions"><button type="button" (click)="cancelConfirmation()" [disabled]="dialogBusy">Cancel</button><button class="primary-button" type="button" (click)="confirmPending()" [disabled]="dialogBusy">Confirm</button></div></dialog> }
      <p class="privacy-note" role="note">Authenticated operation data is memory-only. Live notifications contain resource metadata only; annotation text, notes, query bodies, grouping values, and evidence values are never placed in URLs or SSE.</p>
    </section>
  `,
  styles: [`
    :host { display:block; min-width:0; max-width:100%; } .operations { contain:paint; display:grid; gap:1rem; grid-template-columns:minmax(0,1fr); min-width:0; max-width:100%; overflow:hidden; width:100%; } .section-heading,.panel-heading { align-items:flex-start; display:flex; flex-wrap:wrap; gap:1rem; justify-content:space-between; } h2,h3,h4 { margin:0; overflow-wrap:anywhere; } h2 { font-size:1.35rem; } h3 { font-size:1.05rem; } h4 { font-size:.98rem; } .eyebrow { color:var(--accent-hover); font-size:.72rem; font-weight:800; letter-spacing:.08em; margin:0 0 .35rem; text-transform:uppercase; } .muted { color:var(--text-muted); font-size:.84rem; line-height:1.45; margin:.35rem 0 0; overflow-wrap:anywhere; } .heading-actions,.inline-actions,.legend { align-items:center; display:flex; flex-wrap:wrap; gap:.55rem; } .legend-item { align-items:center; display:inline-flex; gap:.25rem; } button,input,select,textarea { border-radius:.45rem; font:inherit; max-width:100%; min-height:2.4rem; } button { background:var(--surface); border:1px solid var(--control-border); color:var(--text); cursor:pointer; font-weight:700; padding:.5rem .7rem; } button:hover { background:var(--surface-subtle); } button:disabled { cursor:not-allowed; opacity:.55; } button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.workspace-tabs button:focus-visible { outline:3px solid var(--focus); outline-offset:3px; } .primary-button { background:var(--accent); border-color:var(--accent); color:var(--on-accent); } .secondary-button { background:transparent; } .workspace-tabs { border-bottom:1px solid var(--border); display:flex; gap:.2rem; max-width:100%; overflow-x:auto; } .workspace-tabs button { background:transparent; border:0; border-bottom:3px solid transparent; border-radius:0; color:var(--text-muted); min-height:2.9rem; white-space:nowrap; } .workspace-tabs button.active { border-bottom-color:var(--accent); color:var(--text); } .tab-count { background:var(--danger-surface); border-radius:999px; color:var(--danger-text); font-size:.7rem; margin-left:.35rem; padding:.15rem .4rem; } .panel { background:var(--surface); border:1px solid var(--border); border-radius:.8rem; min-width:0; padding:1rem; } .workspace-grid { display:grid; gap:1rem; grid-template-columns:minmax(0,1fr) minmax(0,1.25fr); min-width:0; } .workspace-skeleton { background:var(--surface); border:1px solid var(--border); border-radius:.8rem; display:grid; gap:.8rem; padding:1.2rem; } .workspace-skeleton span { background:var(--surface-subtle); border-radius:.5rem; display:block; height:3rem; } .workspace-skeleton p { color:var(--text-muted); margin:0; } .dashboard-skeleton { background:var(--surface-raised); border:1px solid var(--border); border-radius:.5rem; color:var(--text-muted); padding:1rem; } .metric-freshness { color:var(--text-muted); font-size:.78rem; margin:.6rem 0; } .form-grid { align-items:end; display:grid; gap:.8rem; grid-template-columns:repeat(2,minmax(0,1fr)); margin-top:1rem; } .form-grid label { color:var(--text-muted); display:grid; font-size:.78rem; font-weight:750; gap:.3rem; min-width:0; } .form-grid .wide { grid-column:1/-1; } .alert-picker { border:1px solid var(--border); display:grid; gap:.35rem; min-width:0; padding:.65rem; } .alert-picker legend { color:var(--text-muted); font-size:.78rem; font-weight:750; } .check-label { align-items:center; display:flex !important; gap:.45rem; } .check-label input { min-height:1.2rem; width:auto; } input,select,textarea { background:var(--surface-raised); border:1px solid var(--control-border); color:var(--text); padding:.45rem .55rem; width:100%; } textarea { min-height:7rem; resize:vertical; } .state-chip,.severity { border:1px solid currentColor; border-radius:999px; display:inline-block; font-size:.73rem; font-weight:800; letter-spacing:.01em; padding:.28rem .5rem; text-transform:capitalize; white-space:nowrap; } .state-ready,.state-recovered,.state-resolved,.state-mitigated { background:var(--success-surface); color:var(--success-text); } .state-firing,.state-critical,.state-error { background:var(--danger-surface); color:var(--danger-text); } .state-warning,.state-stale,.state-partial,.state-rejected,.state-inconclusive,.state-no_data,.state-investigating { background:var(--warning-surface); color:var(--warning-text); } .state-disconnected,.state-loading,.state-open { background:var(--info-surface); color:var(--info-text); } .severity-info { background:var(--info-surface); color:var(--info-text); } .severity-warning { background:var(--warning-surface); color:var(--warning-text); } .severity-error,.severity-critical { background:var(--danger-surface); color:var(--danger-text); } .state-panel,.notice { border-radius:.6rem; padding:.8rem 1rem; } .state-panel p { margin:.35rem 0 .65rem; } .failure { background:var(--danger-surface); color:var(--danger-text); } .warning { background:var(--warning-surface); color:var(--warning-text); } .notice { background:var(--info-surface); color:var(--info-text); } .inline-error { background:var(--danger-surface); color:var(--danger-text); margin:.75rem 0 0; padding:.55rem .7rem; } .snapshot-age { color:var(--text-muted); font-size:.78rem; margin:0; } .snapshot-age .state-chip { margin-left:.4rem; } .table-wrap { max-width:100%; min-width:0; overflow-x:auto; overflow-y:visible; overscroll-behavior-inline:contain; scroll-padding-inline:.5rem; } table { border-collapse:collapse; min-width:47rem; width:100%; } th,td { border-bottom:1px solid var(--border); padding:.6rem .45rem; text-align:left; vertical-align:top; } th { font-size:.76rem; } td { font-size:.82rem; } tbody th small { color:var(--text-muted); display:block; font-size:.7rem; font-weight:500; margin-top:.2rem; } .row-actions { display:flex; flex-wrap:wrap; gap:.35rem; } .card-list { display:grid; gap:.7rem; margin-top:.8rem; } .mini-card,.incident-card,.annotation-card { background:var(--surface-subtle); border:1px solid var(--border); border-radius:.65rem; min-width:0; padding:.8rem; } .incident-card,.annotation-card { display:grid; gap:.6rem; } .mono { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:.75rem; overflow-wrap:anywhere; } .compact-label { align-items:center; color:var(--text-muted); display:flex; font-size:.76rem; gap:.35rem; } .compact-label select { min-height:2.1rem; width:auto; } .annotation-text { line-height:1.5; margin:0; overflow-wrap:anywhere; white-space:pre-wrap; } .terminal-note { border-left:4px solid var(--text-muted); color:var(--text-muted); padding-left:.6rem; } .dashboard-panels { display:grid; gap:1rem; grid-template-columns:repeat(auto-fit,minmax(min(16rem,100%),1fr)); margin-top:.8rem; min-width:0; overflow:hidden; } .dashboard-panel { background:var(--surface-subtle); border:1px solid var(--border); border-radius:.6rem; min-width:0; overflow:hidden; padding:.8rem; } .chart { align-items:flex-end; background:var(--surface-raised); border-bottom:2px solid var(--control-border); display:flex; gap:2px; height:6rem; margin:.8rem 0 .4rem; max-width:100%; min-width:0; overflow:hidden; padding:.5rem .4rem 0; } .bar { background:var(--accent); border:1px solid var(--accent); border-radius:.2rem .2rem 0 0; flex:1; min-height:2px; min-width:2px; padding:0; } .trend-chart { background:var(--surface-raised); border-bottom:2px solid var(--control-border); display:block; height:6rem; margin:.8rem 0 .4rem; max-width:100%; min-width:0; overflow:hidden; padding:.5rem .4rem 0; width:100%; } .trend-chart polyline { stroke:var(--accent); stroke-width:2; } .trend-chart polygon { fill:var(--accent); fill-opacity:.28; stroke:var(--accent); stroke-width:1.5; } .dashboard-preview { contain:paint; } .dashboard-preview,.dashboard-series,.visual-slot { max-width:100%; min-width:0; overflow:hidden; } .table-scroll { box-sizing:border-box; contain:paint; max-width:100%; min-width:0; overflow:auto; overscroll-behavior-inline:contain; scroll-padding-inline:.5rem; width:100%; } .table-scroll:focus-visible { outline:3px solid var(--focus); outline-offset:3px; } table.panel-data { min-width:47rem; width:100%; } .panel-data caption { color:var(--text-muted); font-size:.78rem; font-weight:700; margin-bottom:.3rem; text-align:left; } .confirmation-dialog { background:var(--surface); border:2px solid var(--border); border-radius:.8rem; color:var(--text); max-width:min(32rem,calc(100vw - 2rem)); padding:1.2rem; width:100%; } .confirmation-dialog::backdrop { background:rgb(0 0 0 / .58); } .dialog-actions { display:flex; gap:.6rem; justify-content:flex-end; margin-top:1rem; } .privacy-note { border-top:1px solid var(--border); color:var(--text-muted); font-size:.76rem; line-height:1.5; margin:0; padding-top:.8rem; } .empty { color:var(--text-muted); font-size:.86rem; padding:.7rem 0; } .sr-only { block-size:1px; clip-path:inset(50%); inline-size:1px; margin:-1px; overflow:hidden; padding:0; position:absolute; white-space:nowrap; }
    @media (max-width:800px) { .workspace-grid { grid-template-columns:1fr; } }
    @media (max-width:560px) { .form-grid { grid-template-columns:1fr; } .form-grid .wide { grid-column:auto; } .panel { padding:.8rem; } .heading-actions { width:100%; } .heading-actions .secondary-button { margin-left:auto; } }
    @media (max-width:700px) { .dashboard-preview { width:100%; } .dashboard-panels { grid-template-columns:minmax(0,1fr); width:100%; } .dashboard-panel { width:100%; } .table-wrap { overflow-x:auto; overflow-y:visible; } .alert-table-wrap { overflow:visible; } .alert-table, .alert-table tbody, .alert-table tr, .alert-table td, .alert-table th { display:block; min-width:0; width:100%; } .alert-table thead { clip:rect(0,0,0,0); height:1px; margin:-1px; overflow:hidden; position:absolute; width:1px; } .alert-table tbody tr { border:1px solid var(--border); border-radius:.6rem; margin-bottom:.7rem; padding:.35rem; } .alert-table tbody th, .alert-table tbody td { border:0; display:grid; gap:.5rem; grid-template-columns:minmax(6rem,34%) minmax(0,1fr); overflow-wrap:anywhere; padding:.45rem; } .alert-table td::before, .alert-table th[data-label]::before { color:var(--text-muted); content:attr(data-label); font-size:.72rem; font-weight:800; } .alert-table .row-actions { display:grid; grid-template-columns:minmax(0,1fr); position:relative; z-index:2; } .alert-table .row-actions select, .alert-table .row-actions button { position:relative; width:100%; z-index:3; } }
    @media (prefers-reduced-motion:reduce) { *,*::before,*::after { scroll-behavior:auto !important; transition-duration:.01ms !important; } }
    @media (prefers-contrast:more) { button,input,select,textarea,.panel,.state-chip,.severity { border-width:2px; } } @media (forced-colors:active) { button,.state-chip,.severity { border:2px solid ButtonBorder; } .primary-button { background:ButtonFace !important; border:2px solid ButtonBorder !important; color:ButtonText !important; forced-color-adjust:auto; } }
  `],
})
export class ObservatoryOperationsWorkspaceComponent {
  readonly store = inject(OperationsWorkspaceStore);
  private readonly observatoryStore = inject(ObservatoryStore, { optional: true });
  @ViewChild('confirmationDialog') private confirmationDialog?: ElementRef<HTMLDialogElement>;
  readonly tabs: ReadonlyArray<{ readonly id: OperationsWorkspaceTab; readonly label: string }> = [{ id: 'dashboards', label: 'Dashboards' }, { id: 'queries', label: 'Saved queries' }, { id: 'alerts', label: 'Alert triage' }, { id: 'incidents', label: 'Incidents' }, { id: 'annotations', label: 'Annotations' }];
  readonly severities = severityOptions;
  readonly impacts = impactOptions;
  readonly states = incidentStates;
  readonly targets = targetTypes;
  readonly acknowledgementReasons = acknowledgementReasons;
  dashboardName = ''; dashboardDescription = ''; dashboardQueryKey = '';
  queryName = ''; queryMetric = 'operation_duration_ms'; queryWindow = 'twenty_four_hours';
  incidentTitle = ''; incidentSeverity: OperationalSeverity = 'warning'; incidentImpact: IncidentImpact = 'degraded';
  annotationType: typeof targetTypes[number] = 'run'; annotationTarget = ''; annotationVersion = ''; annotationText = '';
  dashboardError: string | null = null; queryError: string | null = null; incidentError: string | null = null; annotationError: string | null = null;
  selectedDashboard: Dashboard | null = null;
  readonly selectedAlertIds = new Set<string>();
  pendingConfirmation: { readonly title: string; readonly resource: string; readonly scope: string; readonly consequence: string; readonly run: () => Promise<void>; readonly restore: HTMLElement | null; readonly fallback: () => HTMLElement | null } | null = null;
  dialogError: string | null = null;
  dialogBusy = false;
  private readonly incidentNext = new Map<string, IncidentState>();
  private readonly alertReasons = new Map<string, AlertAcknowledgementReason>();
  constructor() {
    effect(() => {
      if (this.store.state() === 'unauthorized') { this.observatoryStore?.requireSession(this.store.error() ?? 'Owner Observatory session required.'); this.store.disconnect(); }
      const selected = this.selectedDashboard;
      const dashboards = this.store.data().dashboards?.items ?? [];
      if (!selected || this.store.error() || ['loading', 'stale', 'error', 'rejected', 'unavailable', 'unauthorized'].includes(this.store.state())) return;
      const current = dashboards.find((dashboard) => dashboard.dashboardId === selected.dashboardId && dashboard.dashboardVersion === selected.dashboardVersion);
      if (!current) { this.selectedDashboard = null; return; }
      this.selectedDashboard = current;
      for (const panel of current.panels) {
        const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion);
        if (query) void this.store.executeDashboardQuery(query, panel.visualization, panel.panelId);
      }
    });
    void this.store.load();
  }
  dashboards(): ReadonlyArray<Dashboard> { return this.store.data().dashboards?.items ?? []; }
  presets(): ReadonlyArray<DashboardPreset> { return this.store.data().presets?.items ?? []; }
  queries(): ReadonlyArray<SavedQuery> { return this.store.data().queries?.items ?? []; }
  instances(): ReadonlyArray<AlertInstance> { return this.store.data().instances?.items ?? []; }
  suppressions(): ReadonlyArray<AlertSuppression> { return this.store.data().suppressions?.items ?? []; }
  incidents(): ReadonlyArray<Incident> { return this.store.data().incidents?.items ?? []; }
  annotations() { return this.store.data().annotations?.items ?? []; }
  stateLabel(): string { const state = this.store.state(); return state === 'ready' ? 'Live operation data' : state === 'partial' ? 'Partial snapshot' : state === 'rejected' ? 'Rejected data' : state === 'stale' ? 'Stale snapshot' : state === 'disconnected' ? 'Disconnected' : state === 'loading' ? 'Loading' : state === 'unauthorized' ? 'Sign-in required' : state === 'unavailable' ? 'Service unavailable' : 'Unavailable'; }
  hasSnapshot(): boolean { return Object.values(this.store.data()).some((value) => value !== null); }
  snapshotAge(value: string | null): string { if (!value) return 'not available'; const timestamp = Date.parse(value); if (!Number.isFinite(timestamp)) return 'not available'; const age = Math.max(0, Date.now() - timestamp); if (age < 60_000) return 'just now'; const minutes = Math.floor(age / 60_000); if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`; const days = Math.floor(hours / 24); return `${days} day${days === 1 ? '' : 's'} ago`; }
  isSnapshotStale(value: string): boolean { return Date.now() - Date.parse(value) > 60_000 || this.store.state() === 'stale' || this.store.state() === 'disconnected'; }
  openTab(tab: OperationsWorkspaceTab): void { this.store.activeTab.set(tab); }
  selectTabFromEvent(event: Event): void { const target = event.target; if (target instanceof HTMLSelectElement && this.tabs.some((tab) => tab.id === target.value)) this.openTab(target.value as OperationsWorkspaceTab); }
  refresh(): void { this.store.refresh(); }
  async createDashboard(): Promise<void> { this.dashboardError = null; const [queryId, queryVersion] = this.dashboardQueryKey.split('|'); if (!queryId || !queryVersion || !this.dashboardName.trim()) return; try { await this.store.createDashboard(this.dashboardName, this.dashboardDescription, queryId, queryVersion); this.dashboardName = ''; this.dashboardDescription = ''; this.dashboardQueryKey = ''; } catch (error) { this.dashboardError = this.errorMessage(error); } }
  async createQuery(): Promise<void> { this.queryError = null; if (!this.queryName.trim()) return; try { await this.store.createSavedQuery(this.queryName, { kind: 'analytics', metric: this.queryMetric, unit: this.queryMetric === 'errors' ? 'count' : 'milliseconds', aggregation: this.queryMetric === 'errors' ? 'sum' : 'p95', window: this.queryWindow, bucket: 'auto', groupBy: 'component', focus: 'all', facets: [], seriesLimit: 12, pointLimit: 200 }); this.queryName = ''; } catch (error) { this.queryError = this.errorMessage(error); } }
  ackReason(instance: AlertInstance): AlertAcknowledgementReason { return this.alertReasons.get(instance.instanceId) ?? 'investigating'; }
  setAckReason(instance: AlertInstance, reason: string): void { if (this.acknowledgementReasons.includes(reason as AlertAcknowledgementReason)) this.alertReasons.set(instance.instanceId, reason as AlertAcknowledgementReason); }
  acknowledge(instance: AlertInstance): void { this.openConfirmation({ title: 'Acknowledge alert instance', resource: instance.instanceId, scope: `Rule ${instance.rule.resourceId} · group ${instance.groupingId}`, consequence: `Record the owner acknowledgement as “${this.ackReason(instance)}” for this exact alert instance. Future state changes remain visible.`, run: () => this.store.acknowledge(instance, this.ackReason(instance)) }); }
  suppress(instance: AlertInstance): void { this.openConfirmation({ title: 'Suppress alert instance', resource: instance.instanceId, scope: `Alert group ${instance.groupingId}`, consequence: 'This hides repeated notifications until the suppression is cleared; the observation remains available.', run: () => this.store.suppress(instance) }); }
  clearSuppression(suppression: AlertSuppression): void { this.openConfirmation({ title: 'Clear suppression', resource: suppression.target.resourceId, scope: `${suppression.scope} suppression`, consequence: 'Future matching alerts can notify the owner again.', run: () => this.store.clearSuppression(suppression) }); }
  toggleAlert(id: string): void { if (this.selectedAlertIds.has(id)) this.selectedAlertIds.delete(id); else this.selectedAlertIds.add(id); }
  async createIncident(): Promise<void> { this.incidentError = null; if (!this.incidentTitle.trim() || !this.selectedAlertIds.size) { this.incidentError = 'Choose at least one firing alert for the incident.'; return; } try { await this.store.createIncident(this.incidentTitle, this.incidentSeverity, this.incidentImpact, this.selectedAlertIds); this.incidentTitle = ''; this.selectedAlertIds.clear(); } catch (error) { this.incidentError = this.errorMessage(error); } }
  nextStates(incident: Incident): ReadonlyArray<IncidentState> { return incident.state === 'open' ? ['investigating', 'mitigated', 'resolved'] : incident.state === 'investigating' ? ['mitigated', 'resolved', 'open'] : incident.state === 'mitigated' ? ['investigating', 'resolved', 'open'] : incident.state === 'resolved' ? ['closed', 'investigating'] : []; }
  nextIncidentState(incident: Incident): IncidentState { return this.incidentNext.get(incident.incidentId) ?? this.nextStates(incident)[0] ?? incident.state; }
  setNextIncidentState(incident: Incident, state: IncidentState): void { this.incidentNext.set(incident.incidentId, state); }
  transitionIncident(incident: Incident): void { const state = this.nextIncidentState(incident); if (!this.nextStates(incident).includes(state)) return; this.openConfirmation({ title: `Transition incident to ${state}`, resource: incident.incidentId, scope: `${incident.state} → ${state}`, consequence: 'This audited transition changes the operational lifecycle and cannot be undone from this view.', run: () => this.store.transitionIncident(incident, state, incident.impact, state === 'resolved' ? 'Resolved through Observatory owner workflow.' : null) }); }
  async createAnnotation(): Promise<void> { this.annotationError = null; if (!this.annotationTarget.trim() || !this.annotationVersion.trim() || !this.annotationText.trim()) return; try { await this.store.createAnnotation(this.annotationType, this.annotationTarget, this.annotationVersion, this.annotationText); this.annotationText = ''; } catch (error) { this.annotationError = this.errorMessage(error); } }
  deleteAnnotation(annotation: { readonly annotationId: string; readonly annotationVersion: string; }): void { this.openConfirmation({ title: 'Delete annotation', resource: annotation.annotationId, scope: 'This exact annotation target', consequence: 'The annotation is permanently removed while its content-free audit record remains.', run: () => this.store.deleteAnnotation(annotation as never), fallback: () => document.getElementById('annotation-heading') }); }
  selectDashboard(dashboard: Dashboard): void { this.selectedDashboard = dashboard; for (const panel of dashboard.panels) { const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion); if (query) void this.store.executeDashboardQuery(query, panel.visualization, panel.panelId); } }
  dashboardExecution(panel: DashboardPanel): DashboardExecution | null { const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion); const key = query ? dashboardExecutionKey(query, panel.panelId, panel.visualization) : 'missing'; const execution = query ? this.store.dashboardExecutions()[key] : undefined; return query ? execution ?? { state: 'loading', kind: query.definition.kind, snapshot: null, result: null, freshness: null, snapshotAt: null, nextCursor: null, error: 'Waiting for query execution.' } : { state: 'unavailable', kind: 'analytics', snapshot: null, result: null, freshness: null, snapshotAt: null, nextCursor: null, error: 'Saved query definition unavailable.' }; }
  retryDashboard(panel: DashboardPanel): void { const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion); if (query) void this.store.executeDashboardQuery(query, panel.visualization, panel.panelId); }
  dashboardFreshness(snapshot: NonNullable<DashboardExecution['snapshot']>): string { const observed = snapshot.freshness.latestObservedAt ?? snapshot.snapshotAt; return `${snapshot.freshness.state} · observed through ${this.snapshotAge(observed)}`; }
  dashboardExecutionFreshness(execution: DashboardExecution, snapshot: NonNullable<DashboardExecution['snapshot']>): string { const prefix = execution.state === 'loading' ? 'refreshing · ' : execution.state === 'error' ? 'stale · ' : ''; return `${prefix}${this.dashboardFreshness(snapshot)}`; }
  dashboardResultFreshness(execution: DashboardExecution, result: NonNullable<DashboardExecution['result']>): string {
    const observed = execution.freshness?.measuredAt ?? execution.snapshotAt;
    const prefix = execution.state === 'loading' ? 'refreshing · ' : execution.state === 'error' ? 'stale · ' : '';
    return `${prefix}${result.kind} · ${execution.freshness?.state ?? 'fresh'} · observed through ${this.snapshotAge(observed)}`;
  }
  healthPoints(result: NonNullable<DashboardExecution['result']>): ReadonlyArray<{ readonly startAt: string; readonly endAt: string; readonly summary: { readonly sampleCount: number; readonly latencyP50Ms: number | null; readonly latencyP95Ms: number | null; readonly errorRate: number | null } }> { return result.kind === 'component_health' ? result.value.points : []; }
  dashboardState(snapshot: NonNullable<DashboardExecution['snapshot']>): string { return snapshot.partial ? `partial (${snapshot.partialReasons.join(', ') || 'bounded response'})` : snapshot.series.some((series) => series.availability === 'unavailable') ? 'partially unavailable' : 'measured'; }
  isTrendVisualization(panel: DashboardPanel): boolean { return panel.visualization === 'line' || panel.visualization === 'area' || panel.visualization === 'bar'; }
  panelVisualizationLabel(panel: DashboardPanel): string { return panel.visualization === 'stat' ? 'Summary statistic' : panel.visualization === 'trace' ? 'Trace measurements' : panel.visualization === 'comparison' ? 'Comparison measurements' : panel.visualization === 'regression' ? 'Regression measurements' : `${panel.visualization} trend`; }
  trendAccessibleName(panel: DashboardPanel, seriesKey: string): string { return `${panel.title} ${panel.visualization} trend for ${seriesKey}; point values are available in the accessible UTC table below.`; }
  linePoints(series: NonNullable<DashboardExecution['snapshot']>['series'][number]): string { const points = series.points.filter((point) => point.value !== null); const values = points.map((point) => point.value as number); const min = Math.min(...values, 0); const max = Math.max(...values, 1); const range = Math.max(max - min, 1); return points.map((point, index) => `${points.length > 1 ? (index / (points.length - 1)) * 100 : 50},${100 - (((point.value as number) - min) / range) * 90 - 5}`).join(' '); }
  areaPoints(series: NonNullable<DashboardExecution['snapshot']>['series'][number]): string { const line = this.linePoints(series); return `0,100 ${line} 100,100`; }
  barHeight(value: number | null, series: NonNullable<DashboardExecution['snapshot']>['series'][number]): number { if (value === null) return 0; const values = series.points.flatMap((point) => point.value === null ? [] : [point.value]); const max = Math.max(...values, 0); return max > 0 ? Math.max(4, (value / max) * 100) : 4; }
  panelQueryMetric(panel: DashboardPanel): string { const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion); return query ? (query.definition as { readonly metric?: string }).metric ?? query.definition.kind : 'Query definition unavailable'; }
  panelQueryUnit(panel: DashboardPanel): string { const query = this.queries().find((item) => item.queryId === panel.query.queryId && item.queryVersion === panel.query.queryVersion); return query ? (query.definition as { readonly unit?: string }).unit ?? 'unitless' : '—'; }
  panelState(): string { return this.store.state() === 'partial' ? 'partial' : this.store.state() === 'rejected' ? 'rejected' : this.store.state() === 'unavailable' ? 'unavailable' : 'no measurement in snapshot'; }
  private openConfirmation(action: Omit<NonNullable<ObservatoryOperationsWorkspaceComponent['pendingConfirmation']>, 'restore' | 'fallback'> & { readonly fallback?: () => HTMLElement | null }): void { if (this.dialogBusy || this.pendingConfirmation) return; this.pendingConfirmation = { ...action, fallback: action.fallback ?? (() => document.getElementById('operations-title')), restore: document.activeElement instanceof HTMLElement ? document.activeElement : null }; this.dialogError = null; setTimeout(() => { const dialog = this.confirmationDialog?.nativeElement; if (dialog && !dialog.open) dialog.showModal(); dialog?.querySelector<HTMLButtonElement>('button')?.focus(); }); }
  private restoreFocus(action: NonNullable<ObservatoryOperationsWorkspaceComponent['pendingConfirmation']>): void { if (action.restore?.isConnected) action.restore.focus(); else action.fallback()?.focus(); }
  cancelConfirmation(): void { if (this.dialogBusy) return; this.confirmationDialog?.nativeElement.close(); const action = this.pendingConfirmation; this.pendingConfirmation = null; this.dialogError = null; if (action) this.restoreFocus(action); }
  async confirmPending(): Promise<void> { const action = this.pendingConfirmation; if (!action || this.dialogBusy) return; this.dialogBusy = true; this.dialogError = null; try { await action.run(); this.confirmationDialog?.nativeElement.close(); this.pendingConfirmation = null; setTimeout(() => this.restoreFocus(action)); } catch (error) { this.dialogError = this.errorMessage(error); } finally { this.dialogBusy = false; } }
  private errorMessage(error: unknown): string { void error; return 'The operation could not be completed. Your draft is preserved; retry when the service is available.'; }
  queryWindowLabel(query: SavedQuery): string { const definition = query.definition as { readonly window?: string }; return definition.window ?? '—'; }
}
